<script setup lang="ts">
import { computed, ref, onMounted, onUnmounted } from 'vue';
import { TabsRoot,TabsList,TabsTrigger,TabsContent,DialogRoot,DialogTrigger,DialogPortal,DialogOverlay,DialogContent,DialogTitle,DialogDescription,DialogClose,TooltipProvider,TooltipRoot,TooltipTrigger,TooltipPortal,TooltipContent } from 'reka-ui';
import { Clock3, CalendarDays, Layers3, Activity, Folder, ChevronRight, ChevronLeft, Settings2, Search, Play, Pause, Download, Check, X, CircleHelp, Radio, GitBranch, Monitor, Bot, ArrowUpRight, SlidersHorizontal, ShieldCheck } from '@lucide/vue';
import { transport,native,type CaptureStatus } from './transport.ts';
import type { Summary,Session,Interval } from '../capture/events.ts';
import { unionSeconds } from '../capture/correlate.ts';
const empty:Summary={intervals:[],unresolved:[],coverage:[],sessions:[],humanSeconds:0,agentSeconds:0,elapsedSeconds:0,childAgentSeconds:0};
const summary=ref<Summary>(empty),status=ref<CaptureStatus|null>(null),error=ref(''),busy=ref(false),project=ref('all'),search=ref(''),selected=ref<Session|null>(null),view=ref('timeline'),settings=ref(false),page=ref('today');
const dateString=(date:Date)=>`${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,'0')}-${String(date.getDate()).padStart(2,'0')}`;
const selectedDate=ref(dateString(new Date()));
const dayStart=computed(()=>new Date(selectedDate.value+'T00:00:00').getTime()/1000);
const dayEnd=computed(()=>{const d=new Date(selectedDate.value+'T00:00:00');d.setDate(d.getDate()+1);return d.getTime()/1000;});
const fullDate=computed(()=>new Date(selectedDate.value+'T12:00:00').toLocaleDateString('en',{weekday:'long',month:'long',day:'numeric'}));
const workspacePath=(s:Session)=>s.cwd||s.workspaceId?.split('::').at(-1)||'Unassigned';
const projectName=(s:Session)=>{const path=workspacePath(s).split('/.orca/')[0];return path.split('/').filter(Boolean).at(-1)||'Unassigned';};
const projects=computed(()=>[...new Set(summary.value.sessions.map(projectName))].sort());
const palette=['#6875db','#31a783','#d49542','#b278c5','#5b9cc4','#d07878'];
const color=(s:Session)=>palette[Math.max(0,projects.value.indexOf(projectName(s)))%palette.length];
const duration=(seconds:number)=>{const mins=Math.floor(seconds/60);return mins>=60?`${Math.floor(mins/60)}h ${String(mins%60).padStart(2,'0')}m`:mins>0?`${mins}m`:`${Math.round(seconds)}s`;};
const clock=(seconds:number)=>new Date(seconds*1000).toLocaleTimeString('en',{hour:'2-digit',minute:'2-digit',hour12:false});
const dayIntervals=computed(()=>summary.value.intervals.filter(i=>i.end>dayStart.value&&i.start<dayEnd.value).map(i=>({...i,start:Math.max(i.start,dayStart.value),end:Math.min(i.end,dayEnd.value)})));
function belongs(i:Interval,s:Session){return s.child?i.child&&i.sessionId===s.sessionId&&i.agentId===s.agentId:s.dispatchId?i.dispatchId===s.dispatchId&&!i.child:i.sessionId===s.sessionId&&!i.child;}
const sessions=computed(()=>summary.value.sessions.map(s=>({...s,seconds:unionSeconds(dayIntervals.value.filter(i=>i.state==='running'&&belongs(i,s)).map(i=>[i.start,i.end]))})).filter(s=>(project.value==='all'||projectName(s)===project.value)&&(!search.value||[s.title,projectName(s),s.runId,s.provider].join(' ').toLowerCase().includes(search.value.toLowerCase()))).sort((a,b)=>b.seconds-a.seconds||b.lastObservedAt-a.lastObservedAt));
const visibleSessions=computed(()=>sessions.value.filter(s=>s.seconds>0||['working','running','waiting','pending'].includes(s.state)||(s.sessionId&&!s.child)));
const filteredIntervals=computed(()=>dayIntervals.value.filter(i=>project.value==='all'||visibleSessions.value.some(s=>belongs(i,s))));
const agentTime=computed(()=>visibleSessions.value.filter(s=>!s.child).reduce((sum,s)=>sum+s.seconds,0));
const humanTime=computed(()=>project.value==='all'?unionSeconds(dayIntervals.value.filter(i=>i.state==='human').map(i=>[i.start,i.end])):0);
const elapsedTime=computed(()=>unionSeconds(filteredIntervals.value.filter(i=>i.state!=='waiting').map(i=>[i.start,i.end])));
const runningCount=computed(()=>visibleSessions.value.filter(s=>['working','running'].includes(s.state)&&Date.now()/1000-s.lastObservedAt<20).length);
const runs=computed(()=>[...new Set(visibleSessions.value.map(s=>s.runId).filter(Boolean))].length);
const timelineGroups=computed(()=>{
 const groups=new Map<string,{key:string;name:string;sessions:Session[]}>();
 for(const session of visibleSessions.value.slice(0,40)){
  const key=projectName(session)+':'+(session.runId||'independent');
  const group=groups.get(key)||{key,name:session.runId?`${projectName(session)} / Run ${session.runId.slice(-6)}`:`${projectName(session)} / Independent sessions`,sessions:[]};
  group.sessions.push(session);groups.set(key,group);
 }
 return [...groups.values()].map(group=>({...group,sessions:group.sessions.sort((a,b)=>{
  if(a.sessionId===b.sessionId&&a.child!==b.child)return a.child?1:-1;
  return (a.sessionId||a.key).localeCompare(b.sessionId||b.key)||(a.child?1:0)-(b.child?1:0);
 })}));
});
const issues=computed(()=>[...new Set([...summary.value.coverage,...summary.value.unresolved].map(i=>i.reason))]);
const rangeStart=computed(()=>{const first=filteredIntervals.value[0]?.start;return first?Math.max(0,new Date(first*1000).getHours()-1):8;});
const rangeEnd=computed(()=>{const latest=Math.max(...filteredIntervals.value.map(i=>i.end),dayStart.value+18*3600);return Math.min(24,Math.max(rangeStart.value+6,new Date(latest*1000).getHours()+1));});
const hours=computed(()=>Array.from({length:rangeEnd.value-rangeStart.value+1},(_,i)=>rangeStart.value+i));
const timelineStart=computed(()=>dayStart.value+rangeStart.value*3600),timelineSpan=computed(()=>(rangeEnd.value-rangeStart.value)*3600);
const bars=(s:Session)=>dayIntervals.value.filter(i=>belongs(i,s)&&i.state!=='human');
const barStyle=(i:Interval,s:Session)=>({left:`${(i.start-timelineStart.value)/timelineSpan.value*100}%`,width:`${Math.max(.18,(i.end-i.start)/timelineSpan.value*100)}%`,background:color(s)});
const lastSync=computed(()=>status.value?.lastPoll?new Date(status.value.lastPoll*1000).toLocaleTimeString('en',{hour:'2-digit',minute:'2-digit',hour12:false}):'Not yet captured');
let timer:ReturnType<typeof setInterval>|undefined;
async function refresh(){try{const [s,meta]=await Promise.all([transport.summary(),transport.status()]);summary.value=s;status.value=meta;error.value='';}catch(e){error.value=String(e);}}
async function toggleCapture(){busy.value=true;try{status.value=status.value?.running?await transport.stop():await transport.start();await refresh();}catch(e){error.value=String(e);}finally{busy.value=false;}}
function changeDay(amount:number){const date=new Date(selectedDate.value+'T12:00:00');date.setDate(date.getDate()+amount);selectedDate.value=dateString(date);selected.value=null;}
function exportCsv(){const headers=['Project','Session','Run','Task','Agent seconds','State','Proof'];const rows=visibleSessions.value.map(s=>[projectName(s),s.title,s.runId||'',s.taskId||'',String(Math.round(s.seconds)),s.state,s.proof]);const csv=[headers,...rows].map(row=>row.map(v=>'"'+v.replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));const a=document.createElement('a');a.href=url;a.download=`agent-time-${selectedDate.value}.csv`;a.click();URL.revokeObjectURL(url);}
function openSettings(e:KeyboardEvent){if((e.metaKey||e.ctrlKey)&&e.key===','){e.preventDefault();settings.value=true;}}
onMounted(()=>{void refresh();timer=setInterval(()=>{void refresh();},5000);window.addEventListener('keydown',openSettings);});
onUnmounted(()=>{clearInterval(timer);window.removeEventListener('keydown',openSettings);});
</script>
<template>
<TooltipProvider :delay-duration="350">
<div class="app-shell">
 <aside class="sidebar">
  <div class="titlebar-space" data-tauri-drag-region></div>
  <div class="brand"><div class="brand-mark"><Clock3 :size="19"/></div><span>Agent Time</span><span class="version">Preview</span></div>
  <div class="sidebar-section"><button :class="['nav-row',{active:page==='today'}]" @click="page='today';project='all'"><CalendarDays :size="17"/><span>My day</span><span class="nav-key">⌘1</span></button><button :class="['nav-row',{active:page==='sessions'}]" @click="page='sessions';view='sessions'"><Layers3 :size="17"/><span>Agent sessions</span><span class="nav-count">{{visibleSessions.length}}</span></button><button :class="['nav-row',{active:page==='health'}]" @click="page='health'"><Activity :size="17"/><span>Capture health</span><span v-if="issues.length" class="issue-dot"></span></button></div>
  <div class="section-label">Projects <span>{{projects.length}}</span></div>
  <button :class="['project-row',{selected:project==='all'}]" @click="project='all';page='today'"><Folder :size="16"/><span>All projects</span></button>
  <div class="project-list"><button v-for="(name,index) in projects" :key="name" :class="['project-row',{selected:project===name}]" @click="project=name;page='today';selected=null"><span class="project-dot" :style="{background:palette[index%palette.length]}"></span><span>{{name}}</span><ChevronRight :size="12"/></button><p v-if="!projects.length" class="sidebar-empty">Projects appear as Orca sessions are discovered.</p></div>
  <div class="sidebar-footer"><div class="collector-line"><span :class="['status-dot',{live:status?.running}]"></span><span>{{status?.running?'Tracking activity':'Capture paused'}}</span></div><div class="footer-line"><span>Stored on this Mac</span><button class="icon-button" aria-label="Settings" @click="settings=true"><Settings2 :size="15"/></button></div></div>
 </aside>
 <main class="main-pane">
  <header class="toolbar" data-tauri-drag-region><div class="breadcrumbs"><span>{{project==='all'?'All projects':project}}</span><ChevronRight :size="12"/><strong>{{page==='health'?'Capture health':page==='sessions'?'Agent sessions':'My day'}}</strong></div><div class="toolbar-actions"><TooltipRoot><TooltipTrigger as-child><button class="icon-button" aria-label="Export timesheet as CSV" @click="exportCsv"><Download :size="17"/></button></TooltipTrigger><TooltipPortal><TooltipContent class="tooltip">Export timesheet</TooltipContent></TooltipPortal></TooltipRoot><button class="capture-button" :disabled="busy" @click="toggleCapture"><Pause v-if="status?.running" :size="12"/><Play v-else :size="12"/>{{busy?'Connecting…':status?.running?'Pause capture':'Start capture'}}</button></div></header>
  <div v-if="error||status?.lastError" class="error-banner"><CircleHelp :size="16"/><span>{{error||status?.lastError}}</span><button @click="refresh">Retry</button></div>
  <section v-if="page!=='health'" class="day-content">
   <div class="day-heading"><div><h1>{{page==='sessions'?'Agent sessions':fullDate}}</h1><p>{{page==='sessions'?'Independent sessions, grouped by project and orchestration run.': 'A clear view of your work, and the agents working alongside you.'}}</p></div><div class="date-controls"><button class="icon-button" aria-label="Previous day" @click="changeDay(-1)"><ChevronLeft :size="16"/></button><input type="date" aria-label="Choose day" v-model="selectedDate"/><button class="icon-button" aria-label="Next day" @click="changeDay(1)"><ChevronRight :size="16"/></button><button class="today-button" @click="selectedDate=dateString(new Date())">Today</button></div></div>
   <div class="metrics-strip"><div class="metric"><span><Monitor :size="14"/>Mac activity <span class="estimate">Estimated</span></span><strong>{{duration(humanTime)}}</strong><small>{{project==='all'?'Active foreground time; project unassigned':'Human project attribution unavailable'}}</small></div><div class="metric"><span><Bot :size="14"/>Agent time</span><strong>{{duration(agentTime)}}</strong><small>Independent agents counted separately</small></div><div class="metric"><span><Clock3 :size="14"/>Elapsed activity</span><strong>{{duration(elapsedTime)}}</strong><small>Overlapping activity counted once</small></div><div class="metric compact"><span><Radio :size="14"/>Working now</span><strong>{{runningCount}}<span> agents</span></strong><small>{{runs}} orchestration {{runs===1?'run':'runs'}}</small></div></div>
   <TabsRoot v-model="view" class="activity-panel"><div class="panel-toolbar"><TabsList class="segmented"><TabsTrigger value="timeline"><CalendarDays :size="14"/>Timeline</TabsTrigger><TabsTrigger value="sessions"><Layers3 :size="14"/>Sessions</TabsTrigger></TabsList><div class="search-field"><Search :size="14"/><input v-model="search" aria-label="Search sessions" placeholder="Search sessions…"/></div></div>
    <TabsContent value="timeline" class="timeline"><div class="timeline-header"><span>Agent / session</span><div class="hour-labels"><span v-for="hour in hours" :key="hour" :style="{left:`${(hour-rangeStart)/(rangeEnd-rangeStart)*100}%`}">{{String(hour).padStart(2,'0')}}:00</span></div><span class="time-total">Time</span></div>
     <div v-if="!visibleSessions.length" class="empty-state"><div class="empty-icon"><Clock3 :size="29"/></div><h2>Your work will appear here</h2><p>Start capture to discover your Orca sessions.<br/>Time is recorded as activity is observed.</p><button class="primary-button" :disabled="busy||status?.running" @click="toggleCapture">{{status?.running?'Listening for activity…':'Start capture'}}</button></div>
     <div v-for="group in timelineGroups" :key="group.key" class="run-group"><div class="run-group-header"><Layers3 :size="12"/><span>{{group.name}}</span><small>{{group.sessions.filter(s=>!s.child).length}} agents<span v-if="group.sessions.some(s=>s.child)"> · {{group.sessions.filter(s=>s.child).length}} subagents</span></small></div>
     <button v-for="session in group.sessions" :key="session.key" :class="['timeline-row',{focused:selected?.key===session.key,child:session.child}]" @click="selected=session"><div class="session-label"><span class="agent-symbol" :style="{color:color(session),background:color(session)+'16'}"><Bot :size="15"/></span><div><strong>{{session.title}}</strong><small>{{projectName(session)}} <span v-if="session.child">· Subagent</span><span v-else-if="session.runId">· {{session.runId.slice(-6)}}</span></small></div></div><div class="timeline-track"><span v-for="hour in hours" :key="hour" class="grid-line" :style="{left:`${(hour-rangeStart)/(rangeEnd-rangeStart)*100}%`}"></span><span v-for="(interval,index) in bars(session)" :key="index" :class="['time-block',{waiting:interval.state==='waiting',inferred:interval.proof==='inferred'}]" :style="barStyle(interval,session)" :title="`${clock(interval.start)}–${clock(interval.end)} · ${interval.state} · ${interval.proof}`"></span><span v-if="!bars(session).length" class="no-interval">{{session.state==='completed'?'No duration observed':'Waiting for timing evidence'}}</span></div><span class="time-total">{{duration(session.seconds)}}</span></button>
     </div>
     <div class="timeline-legend"><span><i class="legend-solid"></i>Observed activity</span><span><i class="legend-inferred"></i>Sampled activity</span><span><i class="legend-wait"></i>Known waiting</span><span class="legend-note">Gaps stay uncounted</span></div>
    </TabsContent>
    <TabsContent value="sessions" class="sessions-table"><table><thead><tr><th>Session</th><th>Project / run</th><th>Status</th><th>Agent time</th><th>Evidence</th></tr></thead><tbody><tr v-for="session in sessions.slice(0,100)" :key="session.key" tabindex="0" @click="selected=session" @keydown.enter="selected=session"><td><strong>{{session.title}}</strong><small>{{session.provider||'Unknown agent'}}{{session.child?' · Subagent':''}}</small></td><td>{{projectName(session)}}<small>{{session.runId||'Independent session'}}</small></td><td><span :class="['state-pill',{working:['working','running'].includes(session.state)}]">{{session.state}}</span></td><td class="tabular">{{duration(session.seconds)}}</td><td>{{session.proof}}</td></tr><tr v-if="!sessions.length"><td colspan="5" class="table-empty">No sessions discovered for this project yet.</td></tr></tbody></table></TabsContent>
   </TabsRoot>
   <div class="activity-note"><ShieldCheck :size="14"/><span>Local capture. Human activity is estimated; session timing shows its evidence.</span><span class="sync-note">Last sync {{lastSync}}</span></div>
  </section>
  <section v-else class="health-content"><h1>Capture health</h1><p>What this Mac can observe, and where the evidence is incomplete.</p><div class="health-grid"><article><Monitor :size="20"/><h3>macOS activity</h3><strong>{{status?.macos?'Receiving observations':'Not observed yet'}}</strong><p>Foreground app: {{status?.macos?.foregroundName||'Unknown'}}<br/>Idle: {{status?.macos?duration(Number(status.macos.idleSeconds)||0):'Unknown'}}</p></article><article><Layers3 :size="20"/><h3>Session capture</h3><strong>{{status?.eventCount||0}} events stored</strong><p>{{summary.sessions.length}} discovered sessions<br/>{{summary.sessions.filter(s=>s.sessionId).length}} with provider session IDs</p></article><article><GitBranch :size="20"/><h3>Human attribution</h3><strong>Project unassigned</strong><p>Focused Orca session identification is not yet verified. Human time is kept separate.</p></article></div><h2>Coverage and unresolved evidence</h2><ul class="issue-list"><li v-for="issue in issues.slice(0,50)" :key="issue"><CircleHelp :size="15"/><span>{{issue}}</span></li><li v-if="!issues.length"><Check :size="15"/><span>No recorded capture errors. Unsupported scenarios still need validation.</span></li></ul></section>
  <footer class="statusbar"><span><span :class="['status-dot',{live:status?.running}]"></span>{{status?.running?'Collector running':'Collector paused'}}</span><span>{{native?'Desktop app':'Local browser preview'}} · {{summary.sessions.length}} discovered sessions</span></footer>
 </main>
 <aside v-if="selected" class="inspector"><div class="inspector-toolbar"><span>Session details</span><button class="icon-button" aria-label="Close session details" @click="selected=null"><X :size="16"/></button></div><span class="inspector-icon" :style="{color:color(selected)}"><Bot :size="27"/></span><h2>{{selected.title}}</h2><span class="state-pill">{{selected.state}}</span><dl><dt>Project</dt><dd>{{projectName(selected)}}</dd><dt>Agent</dt><dd>{{selected.provider||'Unknown'}}</dd><dt>Observed agent time</dt><dd class="inspector-duration">{{duration(selected.seconds)}}</dd><dt>Evidence</dt><dd>{{selected.proof}}</dd><dt>Orchestration run</dt><dd>{{selected.runId||'Independent session'}}</dd><dt>Task / attempt</dt><dd>{{selected.taskId||'Unassigned'}}<br/>{{selected.dispatchId||'No dispatch'}}</dd><dt>Provider session</dt><dd>{{selected.sessionId||'Not yet linked'}}</dd><dt>Workspace</dt><dd class="path">{{workspacePath(selected)}}</dd></dl><p class="inspector-note">Retained terminals do not extend a completed task’s time. Native child time is shown separately.</p></aside>
</div>
<DialogRoot v-model:open="settings"><DialogPortal><DialogOverlay class="dialog-overlay"/><DialogContent class="settings-dialog"><DialogTitle>Capture settings</DialogTitle><DialogDescription>Tracking stays on this Mac. This preview validates capture before billing or project-level human attribution.</DialogDescription><div class="setting-row"><span>Activity sampling</span><strong>Every 5 seconds</strong></div><div class="setting-row"><span>Idle threshold</span><strong>5 minutes</strong></div><div class="setting-row"><span>Human session attribution</span><strong>Unverified</strong></div><div class="setting-row"><span>When you close the window</span><strong>Keep collecting</strong></div><p class="settings-note">Quit Agent Time from the application menu to stop the collector. Agent hooks must be installed for exact session identity; Orca polling provides sampled activity.</p><DialogClose class="primary-button">Done</DialogClose><DialogClose class="dialog-x" aria-label="Close settings"><X :size="16"/></DialogClose></DialogContent></DialogPortal></DialogRoot>
</TooltipProvider>
</template>
